vulnerable_code:
app.delete('/api/cart/:itemId', (req, res) => {
  db('cart_items')
    .where('id', req.params.itemId)
    .del()
    .then(() => res.send('Item removed'))
    .catch(err => res.status(500).send(err.message));
});

corrected_code:
app.delete('/api/cart/:itemId', (req, res) => {
  db('cart_items')
    .where({ id: req.params.itemId, user_id: req.user.id })
    .del()
    .then(count => count ? res.send('Item removed') : res.status(404).send('Not found'))
    .catch(err => res.status(500).send(err.message));
});
